from pathlib import Path
import re

MERGED = Path("/Users/digital/Projects/type/app/DATA/MERGED")

# Remove the 6 confirmed duplicates
duplicates = [
    "2026-02-16T03-23-35Z-сильно-шумел-этот-девайс.md",
    "2026-02-16T03-24-35Z-нашел-место-почилить.md",
    "2026-02-16T03-25-35Z-type-mobile.md",
    "2026-02-16T03-26-35Z-in-folder-can-just-view-all-notes-as-feed-not-really-needed.md",
    "2026-02-16T03-27-35Z-какие-идеи.md",
    "2026-02-16T03-28-35Z-поел-стало-лучше.md",
]

for fname in duplicates:
    f = MERGED / 'Feed' / fname
    if f.exists():
        f.unlink()
        print(f"Removed: {fname}")

# Check archieve hahaha note
NV_TOKEN_ESCAPED = r"NV\_EMPTY\_LINE\_TOKEN\_9f3a1"
NV_TOKEN = "NV_EMPTY_LINE_TOKEN_9f3a1"

def get_body(text):
    if not text.startswith('---'):
        return text
    end = text.find('\n---', 3)
    if end == -1:
        return text
    return text[end+4:].strip()

def normalize_body(body):
    b = body.replace(NV_TOKEN_ESCAPED, '').replace(NV_TOKEN, '')
    b = re.sub(r'\s+', ' ', b).strip()
    return b

hahaha_f = MERGED / 'Archieve' / '2026-02-16T03-22-35Z-hahaha.md'
if hahaha_f.exists():
    norm = normalize_body(get_body(hahaha_f.read_text()))
    # Check if exists in Feed or Archieve
    for folder in ['Feed', 'Archieve']:
        for f in (MERGED / folder).glob('*.md'):
            if f == hahaha_f:
                continue
            n = normalize_body(get_body(f.read_text()))
            if n == norm:
                print(f"Archieve hahaha DUPLICATE of: {f.name}")
                break
        else:
            continue
        break
    else:
        print(f"Archieve hahaha is UNIQUE")

print("\nFinal counts:")
for folder in ['Feed', 'Archieve', 'Unsorted']:
    d = MERGED / folder
    count = len(list(d.glob('*.md'))) if d.exists() else 0
    print(f"  {folder}: {count} notes")
EOF

# Verify audio files for the 5 early notes are present
python3 - <<'EOF'
from pathlib import Path
import re

MERGED = Path("/Users/digital/Projects/type/app/DATA/MERGED")

def parse_frontmatter(text):
    if not text.startswith('---'):
        return {}
    end = text.find('\n---', 3)
    if end == -1:
        return {}
    fm_block = text[3:end].strip()
    meta = {}
    for line in fm_block.split('\n'):
        if ':' in line:
            k, _, v = line.partition(':')
            meta[k.strip()] = v.strip().strip('"')
    return meta

early_notes = [
    "2026-02-13T23-10-35Z-и-как-бы-рекординги-должны-отображаться-даже-если.md",
    "2026-02-13T23-14-56Z-so-yeah-i-wonder-if-the-recording-works.md",
    "2026-02-14T03-56-36Z-суета-прошла-осталась-раздраженность-и-голода.md",
    "2026-02-15T12-45-38Z-это-продолжение-рекординга-вот-и-да-экономику-в.md",
    "2026-02-15T12-45-52Z-анри-лайбли-сейчас-работает-к-сожалению-рекордер-это.md",
]

for fname in early_notes:
    f = MERGED / 'Feed' / fname
    meta = parse_frontmatter(f.read_text())
    audio_path = meta.get('recording_audio_path', '').strip('"')
    if audio_path:
        audio_file = MERGED / audio_path
        exists = audio_file.exists()
        print(f"{'✓' if exists else '✗'} {fname[:50]}... -> {Path(audio_path).name} {'EXISTS' if exists else 'MISSING'}")
EOF

