python3 - <<'EOF'
import re
from datetime import datetime, timezone
from pathlib import Path

MERGED_FEED = Path("/Users/digital/Projects/type/app/DATA/MERGED/Feed")
NV_TOKEN_ESCAPED = r"NV\_EMPTY\_LINE\_TOKEN\_9f3a1"
NV_TOKEN = "NV_EMPTY_LINE_TOKEN_9f3a1"

def ms_to_utc_prefix(ms):
    dt = datetime.fromtimestamp(ms / 1000.0, tz=timezone.utc)
    return dt.strftime("%Y-%m-%dT%H-%M-%SZ")

def make_slug(text, max_len=60):
    text = re.sub(r'[#*`_\[\]()>]', '', text)
    text = text.strip().lower()
    text = re.sub(r'[\s\-]+', '-', text)
    text = re.sub(r'[^\w\-]', '', text, flags=re.UNICODE)
    return text.strip('-')[:max_len] or "note"

def parse_frontmatter(text):
    if not text.startswith('---'):
        return {}, text
    end = text.find('\n---', 3)
    if end == -1:
        return {}, text
    fm_block = text[3:end].strip()
    body = text[end+4:]
    meta = {}
    for line in fm_block.split('\n'):
        if ':' in line:
            k, _, v = line.partition(':')
            meta[k.strip()] = v.strip().strip('"')
    return meta, body

def get_first_content_line(body):
    for line in body.split('\n'):
        line = line.replace(NV_TOKEN_ESCAPED, '').replace(NV_TOKEN, '').strip()
        if not line:
            continue
        line = re.sub(r'^#+\s*', '', line).strip()
        if line.startswith('<!--') or line.startswith('-->'):
            continue
        if line:
            return line
    return ""

for f in sorted(MERGED_FEED.glob("New note*.md")):
    text = f.read_text()
    meta, body = parse_frontmatter(text)
    created_ms = int(meta.get('created_ms', 0))
    utc_prefix = ms_to_utc_prefix(created_ms)
    first_line = get_first_content_line(body)
    slug = make_slug(first_line) if first_line else "note"
    new_name = f"{utc_prefix}-{slug}.md"
    dst = MERGED_FEED / new_name
    if dst.exists():
        print(f"COLLISION: {f.name} -> {new_name}")
        continue
    f.rename(dst)
    print(f"Renamed: {f.name} -> {new_name}")
EOF

