225	  const createNewNote = useCallback(
226	    async (
227	      preferredFolderPath?: string,
228	      initialContent = "",
229	      targetTimestampMs?: number
230	    ) => {
231	      const treeSnapshot = tree ?? (await api.getTree());
232	      const initialFolderPath = preferredFolderPath?.trim() || FEED_FOLDER_PATH;
233	      const targetNode =
234	        findNode(treeSnapshot, initialFolderPath) || findNode(treeSnapshot, FEED_FOLDER_PATH);
235	      if (!targetNode) return null;
236	      const folderPath = targetNode.path;
237	      const created = await api.createNote(
238	        folderPath,
239	        initialContent,
240	        targetTimestampMs,
241	        syncSettings.noteFileNameFormat
242	      );
243	      const path = created.path;
244	      await refreshTree();
245	
246	      setSelectedFolders(new Set([folderPath]));
247	      setLastSelectedFolder(folderPath);
248	      setActiveFolder(folderPath);
249	      setSelectedNotes(new Set([path]));
250	      setLastSelectedNote(path);
251	      setActiveNote(path);
252	      clearDraft();
253	
254	      requestAnimationFrame(() => {
255	        const editorElement =
256	          rightPaneRef.current?.querySelector<HTMLElement>(
257	            ".tiptap-content[contenteditable='true']"
258	          ) || rightPaneRef.current;
259	        focusNoScroll(editorElement);
260	      });
261	
262	      return path;
263	    },
264	    [
265	      clearDraft,
266	      refreshTree,
267	      rightPaneRef,
268	      setActiveFolder,
269	      setActiveNote,
270	      setLastSelectedFolder,
271	      setLastSelectedNote,
272	      setSelectedFolders,
273	      setSelectedNotes,
274	      syncSettings.noteFileNameFormat,
275	      tree,
276	    ]
277	  );
278	
279	  // -- Rename
280	  const startRenameFolder = useCallback((path: string) => {
281	    if (isSystemFolder(path)) {
282	      window.alert(`"${path}" is a fixed folder and cannot be renamed.`);
283	      return;
284	    }
285	    const name = path.split("/").pop() || "";
286	    setRenamingFolder(path);
287	    setRenameValue(name);
288	  }, []);
289	
290	  const submitRenameFolder = useCallback(async () => {
291	    if (!renamingFolder || !renameValue.trim()) {
292	      setRenamingFolder(null);
293	      return;
294	    }
295	    const wasSelected = selectedFolders.has(renamingFolder);
296	    const wasActive = activeFolder === renamingFolder;
297	    const newPath = await api.renameItem(renamingFolder, renameValue.trim());
298	    setRenamingFolder(null);
299	    setRenameValue("");
300	    await refreshTree();
301	    if (wasActive) setActiveFolder(newPath);
302	    if (wasSelected) {
303	      const nextSelected = new Set(selectedFolders);
304	      nextSelected.delete(renamingFolder);
305	      nextSelected.add(newPath);
306	      setSelectedFolders(nextSelected);
307	      setLastSelectedFolder(newPath);
308	    }
309	  }, [activeFolder, refreshTree, renamingFolder, renameValue, selectedFolders, setActiveFolder, setLastSelectedFolder, setSelectedFolders]);
310	
311	  const cancelRenameFolder = useCallback(() => {
312	    setRenamingFolder(null);
313	    setRenameValue("");
314	  }, []);
315	
316	  const renameFolderFromMobile = useCallback(
317	    async (path: string, nextName: string) => {
318	      if (isSystemFolder(path)) {
319	        window.alert(`"${path}" is a fixed folder and cannot be renamed.`);
320	        return;
321	      }
322	      const currentName = path.split("/").pop() || "";
323	      const normalizedNextName = nextName.trim();
