/// Move any non-system folders sitting at the root into the Folders/ subdirectory.
fn migrate_user_folders_to_subdirectory(root: &Path) -> Result<(), String> {
    let folders_dir = root.join(FOLDERS_SUBDIRECTORY);
    let entries = fs::read_dir(root).map_err(|err| err.to_string())?;
    let mut moved_any = false;

    for entry in entries {
        let entry = entry.map_err(|err| err.to_string())?;
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().to_string();
        if name.starts_with('.') || is_system_folder_name(&name) {
            continue;
        }
        // User folder found at root — move it into Folders/
        if !folders_dir.exists() {
            fs::create_dir_all(&folders_dir).map_err(|err| err.to_string())?;
        }
        let dest = folders_dir.join(&name);
        if !dest.exists() {
            fs::rename(&path, &dest).map_err(|err| err.to_string())?;
            moved_any = true;
        }
    }

    if moved_any {
        // Remove migrated folder names from the root order file.
        let mut order = read_order_file(root);
        order
            .folder_order
            .retain(|n| is_system_folder_name(n) || n == FOLDERS_SUBDIRECTORY);
        write_order_file(root, &order)?;
    }

    Ok(())
}

